{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 주차장 융자 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자기소유 토지를 확보하고 법 제12조제1항에 따른 노외주차장 설치통보를 한 사람 등으로서 주차대수 5대 이상인 평면식 또는 입체식 주차시설을 설치하려는 자는 주차장특별회계로부터 융자를 받을 수 있습니다.",
          "b_ids": "주차장:제26조제1항, 주차장:제26조제1항제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울시 주차장 융자 조건",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "융자를 받으려면 자기소유재산으로서 융자금의 담보능력이 확보되어야 합니다.",
          "b_ids": "주차장:제26조제3항"
        },
        {
          "a_text": "제1항제1호의 입체식주차시설은 평면식주차장의 수용능력의 2배 이상의 규모이어야 합니다.",
          "b_ids": "주차장:제26조제2항"
        },
        {
          "a_text": "융자를 받은 자는 융자금의 상환기간 이상 주차장을 운영하여야 하고, 시장이 주차장 설치 및 운영에 관한 자료 제출을 요구하면 이에 응하여야 합니다.",
          "b_ids": "주차장:제26조제4항, 주차장:제26조제5항"
        },
        {
          "a_text": "융자금을 신청하려면 규칙이 정하는 서류를 첨부하여 시장에게 제출하여야 하며, 융자금의 지급절차·융자한도·상환기간·이자율 등 융자에 필요한 사항은 시장이 따로 정합니다.",
          "b_ids": "주차장:제27조제1항, 주차장:제27조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
